import sys
miss=[]
def R(path,pairs):
    s=open(path,encoding='utf-8').read()
    for a,b in pairs:
        if s.count(a)<1: miss.append((path,a[:80])); continue
        s=s.replace(a,b)
    open(path,'w',encoding='utf-8').write(s)
